class Solution {
    public ListNode swapNodes(ListNode head, int k) {
        List<Integer> values = new ArrayList<>();
        for (ListNode c = head; c != null; c = c.next) values.add(c.val);
        Collections.swap(values, k - 1, values.size() - k);
        int idx = 0;
        for (ListNode c = head; c != null; c = c.next) c.val = values.get(idx++);   // write back
        return head;
    }
}

